window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"3_d8doI4SlU","speaker":"Emmanuel Macron","role":"President","country":"France","region":"Europe","url":"https://www.youtube.com/watch?v=3_d8doI4SlU","date":"20260922","title":"🇫🇷 France -  President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1983,"words":4291,"counts":{"claims":52,"promises":20,"attacks":3},"topics":[{"topic":"AI","share":0.2058,"seconds":408},{"topic":"Africa","share":0.1314,"seconds":260},{"topic":"UN reform","share":0.1062,"seconds":211},{"topic":"Ukraine","share":0.0953,"seconds":189},{"topic":"Ocean","share":0.0667,"seconds":132},{"topic":"Israel-Gaza","share":0.0638,"seconds":127},{"topic":"Imperialism","share":0.0432,"seconds":86},{"topic":"International order","share":0.0392,"seconds":78},{"topic":"Global conflicts","share":0.0345,"seconds":68},{"topic":"Cultural restitution","share":0.0343,"seconds":68},{"topic":"Global trade","share":0.0332,"seconds":66},{"topic":"Multilateralism","share":0.0327,"seconds":65},{"topic":"International law","share":0.0318,"seconds":63},{"topic":"Syria","share":0.0313,"seconds":62},{"topic":"Lebanon","share":0.0304,"seconds":60},{"topic":"Ceremony","share":0.0203,"seconds":40}],"timeline":[[0,86,"Imperialism"],[87,165,"International order"],[165,231,"UN reform"],[231,300,"Global conflicts"],[302,365,"International law"],[368,432,"Israel-Gaza"],[434,517,"UN reform"],[518,584,"Ukraine"],[585,647,"Africa"],[648,714,"Africa"],[714,776,"Ukraine"],[776,837,"Ukraine"],[839,900,"Lebanon"],[902,965,"Israel-Gaza"],[966,1028,"Syria"],[1030,1093,"Africa"],[1094,1165,"Africa"],[1165,1233,"Cultural restitution"],[1238,1304,"Global trade"],[1304,1376,"Ocean"],[1378,1438,"Ocean"],[1439,1502,"AI"],[1503,1570,"AI"],[1571,1633,"AI"],[1634,1724,"AI"],[1724,1786,"AI"],[1789,1852,"AI"],[1853,1918,"Multilateralism"],[1919,1982,"UN reform"],[1983,2023,"Ceremony"]],"stances":{"Imperialism":"Emmanuel Macron states that every speaker has described the return of imperialism, arrogance, and unrestrained force.","International order":"Emmanuel Macron argues for maintaining a civilized international society at the United Nations to protect sovereignty against those who seek to undermine it.","UN reform":"Emmanuel Macron asserts that the UN charter prevents powerful nations from imposing decisions on others and emphasizes France's commitment to reviving multilateralism through collective action.","Global conflicts":"Emmanuel Macron asserts that the international community must defend justice and common interests against the imposition of might over right, rejecting fatalism in the face of growing wars and crises.","International law":"Emmanuel Macron asserts that international law defines limits set by sovereign nations to prevent force from being the only recourse and rejects fatalism regarding war.","Israel-Gaza":"Emmanuel Macron asserts that war crimes have been industrialized in Gaza and other locations, calling for the defense of international humanitarian law and justice.","Ukraine":"Emmanuel Macron states that France and a coalition of willing nations are committed to defending principles in the UN Charter and guaranteeing peace in Europe, while also establishing an independent multinational coalition for navigation security.","Africa":"Emmanuel Macron asserts that France is committed to international law and calls for more effective, better-funded, and coordinated peace operations in Africa involving the US and host nations.","Lebanon":"Emmanuel Macron asserts that only a fully sovereign Lebanon can disarm Hezbollah and restore security, while criticizing the violation of Palestinian rights and the lack of humanitarian access in Gaza.","Syria":"Emmanuel Macron states that France supports building a free Syria and insists on allowing Syria to fully reassert its sovereignty and unity without double standards.","Cultural restitution":"Emmanuel Macron states that France has initiated joint scientific works and legislation to restitute cultural artifacts to countries in the Global South, framing this as a necessary foundation for a new north-south partnership based on respect.","Global trade":"Emmanuel Macron advocates for more effective and equitable global trade, emphasizing dialogue between the G7 and Southern nations to address critical minerals and prevent rifts between economic blocks.","Ocean":"Emmanuel Macron asserts that proactive multilateralism has successfully led to agreements protecting marine areas and high seas, countering previous doubts about the feasibility of such conservation.","AI":"Emmanuel Macron calls for upholding the Paris Agreement and maintaining European agency in artificial intelligence governance against US-China dominance.","Multilateralism":"Emmanuel Macron asserts that the world must return to the spirit of multilateralism in response to abuses of power and monopolization by certain actors.","Ceremony":"Emmanuel Macron expresses optimism and gratitude while concluding his address."},"claims":[{"t":77,"quote":"Every speaker has described the return of imperialism, of arrogance, the return of unrestrained force which knows no rules.","topic":"Imperialism","kind":"fact"},{"t":92,"quote":"A world in which some believe that they can undermine the international order so as to push their borders outwards.","topic":"International order","kind":"fact"},{"t":109,"quote":"People who believe that they can decide the fate of the planet whether that be as regards the climate or AI.","topic":"International order","kind":"fact"},{"t":180,"quote":"It is our charter that prevents the power wielded by some from making decisions for others.","topic":"UN reform","kind":"fact"},{"t":196,"quote":"You know just how committed France is to the United Nations and its ability to shoulder the responsibilities conferred upon it by the charter.","topic":"UN reform","kind":"self_credit"},{"t":265,"quote":"a growing number of wars we haven't solved, multiplying myriad crises and contemporary challenges which are weighing on new generations in new ways","topic":"Global conflicts","kind":"fact"},{"t":284,"quote":"as I've been doing over the last nine years","topic":"Global conflicts","kind":"self_credit"},{"t":335,"quote":"International law never claimed to describe reality. It talked about the limits which sovereign nations themselves set.","topic":"International law","kind":"fact"},{"t":354,"quote":"Those who've forgotten those lessons are committing both a moral error and a political mistake.","topic":"International law","kind":"fact"},{"t":368,"quote":"War crimes have been industrialized. We've seen the destruction of civilian infrastructure, human rights violations.","topic":"Israel-Gaza","kind":"fact"},{"t":380,"quote":"The Geneva Conventions offered a protective framework, but it is being Alfa, Bukavo, Gaza, the list goes on.","topic":"Israel-Gaza","kind":"fact"},{"t":396,"quote":"international effort that aims to uphold international humanitarian law, which over 116 states have already rallied behind","topic":"Israel-Gaza","kind":"number"},{"t":487,"quote":"I'm delighted that it now has the support of 128 member states.","topic":"UN reform","kind":"number"},{"t":532,"quote":"The coalition of the willing on Ukraine together with the UK and Germany.","topic":"Ukraine","kind":"fact"},{"t":536,"quote":"A coalition which brings together everyone who stands ready to guarantee peace and stability in the very heart of Europe.","topic":"Ukraine","kind":"fact"},{"t":618,"quote":"Back in 2018 2018, I already mentioned the role played by regional and better coordination between these regional bodies and the UN at the Africa meeting in Nairobi with over 30 African heads of state and in Adisba the headquarters of the African Union together with the UN.","topic":"Africa","kind":"fact"},{"t":648,"quote":"In Paris in November, we will hold a meeting aimed at replenishing the African Union Peace Fund. This will be on the sidelines of the Paris Peace Forum.","topic":"Africa","kind":"fact"},{"t":692,"quote":"How many times have we heard that uh people's has value in Europe but if we look at the Middle East at Africa it is less valuable.","topic":"Africa","kind":"fact"},{"t":747,"quote":"For almost 5 years now, Russia has been waging a cruel war on civilians.","topic":"Ukraine","kind":"fact"},{"t":751,"quote":"It's been occupying the territory of a sovereign state.","topic":"Ukraine","kind":"fact"},{"t":791,"quote":"A double moratorium, a moratorium on strikes on energy and civilian infrastructure. That's first. and a Black Sea moratorium which would allow us to release grain shipments.","topic":"Ukraine","kind":"fact"},{"t":808,"quote":"Addressing food security concerns, food security being so important for many emerging economies, for many developing nations.","topic":"Ukraine","kind":"fact"},{"t":845,"quote":"Only a fully sovereign Lebanon will be able to disarm Hezbollah and restore security for all Lebanese and their neighbors.","topic":"Lebanon","kind":"fact"},{"t":870,"quote":"One year ago, in this very chamber, several dozen states recognized Palestine.","topic":"Lebanon","kind":"number"},{"t":906,"quote":"Look, just look at look at what's happening in the West Bank where day in day out we are seeing violations","topic":"Israel-Gaza","kind":"fact"},{"t":919,"quote":"Hamas was never very active in the West","topic":"Israel-Gaza","kind":"fact"},{"t":969,"quote":"A few months ago in Damascus, I lent France's support to building a free Syria","topic":"Syria","kind":"fact"},{"t":997,"quote":"We've been committed for 50 years to all Lebanese","topic":"Syria","kind":"number"},{"t":1045,"quote":"For instance, the Kovac initiative in response to CO in partnership with the WHO and the African when it came to shoring up economies together with the International Monetary Fund to reform special drawing rights and uh make progress for African economies.","topic":"Africa","kind":"fact"},{"t":1066,"quote":"And we held our word hundred billion dollars in special drawing allocated to helping African countries.","topic":"Africa","kind":"number"},{"t":1120,"quote":"This is what we did with the Paris Pact for People and Planet in 2023.","topic":"Africa","kind":"fact"},{"t":1124,"quote":"Also at the Africa Forward Summit in Nairobi, we also agreed to build a new consensus around investment that stands in solidarity with other states.","topic":"Africa","kind":"fact"},{"t":1188,"quote":"This is what France has tried to do over the last few years. Working on the basis of joint scientific works, we've instituted a number of you a number of bills to ensure that we restitute cultural artifacts","topic":"Cultural restitution","kind":"fact"},{"t":1242,"quote":"This is what we sought to achieve at the G7 meeting France convened.","topic":"Global trade","kind":"fact"},{"t":1298,"quote":"We've done a great deal over the last few years, ever since the Paris Agreement 11 years ago.","topic":"Global trade","kind":"self_credit"},{"t":1352,"quote":"Just look at what we've done over the last few years, protecting 20 years of uh our land mass and our seas.","topic":"Ocean","kind":"fact"},{"t":1364,"quote":"Some also some also told us that we won't be able wouldn't be able to conserve twothirds of uh our oceans the high seas.","topic":"Ocean","kind":"fact"},{"t":1387,"quote":"we achieved over 60 ratifications, which means that the treaty has now entered into force that agreement","topic":"Ocean","kind":"number"},{"t":1406,"quote":"the first oceans COP will be held in a few months time in January","topic":"Ocean","kind":"fact"},{"t":1468,"quote":"We are already the victims of climate change.","topic":"AI","kind":"fact"},{"t":1484,"quote":"There are some who wish to make us believe that only two powers, the US and China will be taking the decisions.","topic":"AI","kind":"fact"},{"t":1522,"quote":"Starting in 2008 at the G7 with our Canadian friends, we launched the global partnership for artificial intelligence under the opaces of the OECD","topic":"AI","kind":"fact"},{"t":1534,"quote":"to kickstart discussions on the need for at the AI summit in 2025. The AI governance summit the next edition will be held in in Switzerland next year.","topic":"AI","kind":"fact"},{"t":1572,"quote":"Europe was the first with the AI act to take forward these principles to take forward these models","topic":"AI","kind":"fact"},{"t":1598,"quote":"their capacity to learn is in decline. We're seeing mental health The facts are stark and uh the correlation is clear-cut.","topic":"AI","kind":"fact"},{"t":1649,"quote":"together with Kenya, Spain, we've built a coalition on children's in the era of AI.","topic":"AI","kind":"fact"},{"t":1696,"quote":"France is proud to have a competitive frontier model","topic":"AI","kind":"self_credit"},{"t":1747,"quote":"Our investment capabilities must be pulled to build a cutting edge opensource AI model which we will share.","topic":"AI","kind":"fact"},{"t":1789,"quote":"Many of us lent our support for the call launched by our Finnish and Norwegian friends","topic":"AI","kind":"fact"},{"t":1826,"quote":"We did this on chemical weapons. We did this when it came to other risks","topic":"AI","kind":"fact"},{"t":1886,"quote":"The rhetoric of defeat that is giving way to empires abusing their powers, threatening the sovereignty of some nations, abuse of power by some who are monopolizing productive capacity, those who are monopolizing the ability to make calculations, abuses of power by those who wish to concentrate wealth in their own hands.","topic":"Multilateralism","kind":"fact"},{"t":1962,"quote":"I'd like to pay tribute to the efforts of Antonio Gutish over all these years under such testing conditions. He never gave in.","topic":"UN reform","kind":"fact"}],"promises":[{"t":138,"quote":"Our duty today more than ever is to hold firm here at the United Nations in order to make decisions to further our common interests","topic":"International order","kind":"promise"},{"t":204,"quote":"I wish to reassert our commitment to take action hand in hand with each and every one of you so as to revive multilateralism","topic":"UN reform","kind":"promise"},{"t":294,"quote":"we will not yield to fatalism, to defeatism","topic":"Global conflicts","kind":"promise"},{"t":319,"quote":"We will not yield across five areas.","topic":"International law","kind":"promise"},{"t":390,"quote":"Together with Jordan and the ICRC, France is going to continue undertaking efforts to ensure the international effort that aims to uphold international humanitarian law","topic":"Israel-Gaza","kind":"promise"},{"t":418,"quote":"France continues to support politically and the international mechanism aimed at uh collecting evidence and ensuring justice in particular to factf finding missions","topic":"Israel-Gaza","kind":"promise"},{"t":434,"quote":"We will continue lending our support to the International Court of Justice and supporting the central role it plays.","topic":"UN reform","kind":"promise"},{"t":491,"quote":"The campaign will and we are seeking to secure the commitment of each and every permanent member of the security council for this","topic":"UN reform","kind":"promise"},{"t":556,"quote":"We will not yield an inch.","topic":"Ukraine","kind":"promise"},{"t":560,"quote":"The coalition of the willing will continue fighting.","topic":"Ukraine","kind":"promise"},{"t":562,"quote":"We also have an independent multinational coalition aimed at restoring the freedom of navigation in the Homus strait.","topic":"Ukraine","kind":"promise"},{"t":648,"quote":"In Paris in November, we will hold a meeting aimed at replenishing the African Union Peace Fund.","topic":"Africa","kind":"promise"},{"t":753,"quote":"France will continue providing unstinting support for the legitimate aspirations of the Ukrainian people to peace, security, and to a future.","topic":"Ukraine","kind":"promise"},{"t":762,"quote":"At the same time, we will spend no effort to ensure that useful negotiations between Russia and Ukraine begin as swiftly as possible.","topic":"Ukraine","kind":"promise"},{"t":1088,"quote":"We will continue reforming that architecture, but we will never weaken the WH.","topic":"Africa","kind":"promise"},{"t":1214,"quote":"together with all interested parties all interested partners we will work on restorative justice reparations ions","topic":"Cultural restitution","kind":"promise"},{"t":1703,"quote":"We will continue supporting them so that we can have this kind of model","topic":"AI","kind":"promise"},{"t":1747,"quote":"Our investment capabilities must be pulled to build a cutting edge opensource AI model which we will share.","topic":"AI","kind":"promise"},{"t":1796,"quote":"we want to continue within the framework of the G7 but also working closely with our UK colleagues who will hold the chair of the G20 next year","topic":"AI","kind":"promise"},{"t":1820,"quote":"We are coming to an agreement to build a new international architecture","topic":"AI","kind":"promise"}],"attacks":[{"t":100,"quote":"those that believe that uh people's sovereignty can be toppled over that they could use that sovereignty.","topic":"International order","target":"Unnamed opponents"},{"t":159,"quote":"refuse their sovereignty, being taken hostage by injust forces, unjust forces, by fear.","topic":"International order","target":"Unnamed opponents"},{"t":897,"quote":"The spectacle the spectacle it is shameful.","topic":"Lebanon","target":"Israel"}],"greece":[],"said":[{"topic":"AI","said":0.2058,"reported":0.0625,"articles":2},{"topic":"Africa","said":0.1314,"reported":0.0,"articles":0},{"topic":"UN reform","said":0.1062,"reported":0.1875,"articles":6},{"topic":"Ukraine","said":0.0953,"reported":0.1562,"articles":5},{"topic":"Ocean","said":0.0667,"reported":0.0312,"articles":1},{"topic":"Israel-Gaza","said":0.0638,"reported":0.2188,"articles":7},{"topic":"Imperialism","said":0.0432,"reported":0.0,"articles":0},{"topic":"International order","said":0.0392,"reported":0.0938,"articles":3},{"topic":"Global conflicts","said":0.0345,"reported":0.0625,"articles":2},{"topic":"Cultural restitution","said":0.0343,"reported":0.0,"articles":0},{"topic":"Global trade","said":0.0332,"reported":0.0312,"articles":1},{"topic":"Multilateralism","said":0.0327,"reported":0.0312,"articles":1},{"topic":"International law","said":0.0318,"reported":0.0625,"articles":2},{"topic":"Syria","said":0.0313,"reported":0.0,"articles":0},{"topic":"Lebanon","said":0.0304,"reported":0.0312,"articles":1},{"topic":"Ceremony","said":0.0203,"reported":0.0312,"articles":1}],"pickup":[{"outlet":"Naftemporiki","date":"2026-09-22","title":"Μακρόν: Κινδυνεύουν να μείνουν χωρίς θέρμανση εκατομμύρια οικογένειες στην Ουκρανία","url":"https://www.naftemporiki.gr/kosmos/2164943/makron-kindyneyoyn-na-meinoyn-choris-thermansi-ekatommyria-oikogeneies-stin-oykrania","tone":"neutral"},{"outlet":"Naftemporiki","date":"2026-09-22","title":"Η Γαλλία εξετάζει το ενδεχόμενο νέου ψηφίσματος στο ΣΑ του ΟΗΕ για το Στενό του Ορμούζ","url":"https://www.naftemporiki.gr/kosmos/2165159/i-gallia-exetazei-to-endechomeno-neoy-psifismatos-sto-sa-toy-oie-gia-to-steno-toy-ormoyz","tone":"neutral"},{"outlet":"Naftemporiki","date":"2026-09-22","title":"Ο Μακρόν καλεί τον κόσμο να επιλέξει τον ΟΗΕ αντί για τον «νόμο της ζούγκλας»","url":"https://www.naftemporiki.gr/kosmos/2165290/o-makron-kalei-ton-kosmo-na-epilexei-ton-oie-anti-gia-ton-nomo-tis-zoygklas","tone":"neutral"},{"outlet":"Proto Thema","date":"2026-09-22","title":"Μακρόν στον ΟΗΕ: Από το Ορμούζ και την Ουκρανία έως τη Γάζα - Η τελευταία μάχη για έναν κόσμο που δεν θα κυβερνάται μόνο από την ισχύ","url":"https://www.protothema.gr/world/article/1883015/makron-ston-oie-apo-to-ormouz-kai-tin-oukrania-eos-ti-gaza-i-teleutaia-mahi-gia-kosmo-pou-den-tha-kuvernatai-mono-ishu","tone":"neutral"},{"outlet":"In.gr","date":"2026-09-22","title":"Μακρόν: Η αδράνεια για όσα συμβαίνουν στη Γάζα είναι «ντροπή για όλους μας»","url":"https://www.in.gr/2026/09/22/world/makron-i-adraneia-gia-osa-symvainoun-sti-gaza-einai-ntropi-gia-olous-mas","tone":"neutral"},{"outlet":"Iefimerida","date":"2026-09-22","title":"Μακρόν για την Δυτική Όχθη: «Ένα θέαμα που μας ντροπιάζει όλους»","url":"https://www.iefimerida.gr/kosmos/makron-gia-dytiki-ohthi-theama-poy-mas-ntropiazei","tone":"neutral"},{"outlet":"Newsbomb","date":"2026-09-22","title":"Μακρόν στον ΟΗΕ: «Όχι» στον «νόμο της ζούγκλας» - «Ντροπή μας η Γάζα - Προτεραιότητα το Ορμούζ»","url":"https://www.newsbomb.gr/kosmos/story/1765280/makron-ston-oie-oxi-ston-nomo-tis-zoygklas-ntropi-mas-i-gaza-proteraiotita-to-ormoyz","tone":"neutral"},{"outlet":"Ta Nea","date":"2026-09-22","title":"Ξέσπασμα Μακρόν στον ΟΗΕ για τη Γάζα: « Το θέαμα στη Γάζα μας ντροπιάζει όλους»","url":"https://www.tanea.gr/2026/09/22/world/ksespasma-makron-ston-oie-gia-ti-gaza-theama-poy-mas-ntropiazei-oloys","tone":"neutral"},{"outlet":"Efsyn","date":"2026-09-22","title":"Μακρόν από τη Γενική Συνέλευση του ΟΗΕ: «Μας ντροπιάζει όλους» το «θέαμα» στη Γάζα και τη Δυτική Όχθη","url":"https://www.efsyn.gr/kosmos/1472557/makron-apo-ti-geniki-syneleysi-toy-oie-to-theama-sti-gaza-kai-ti-dytiki-ohthi-mas-ntropiazei-oloys","tone":"neutral"},{"outlet":"To Vima","date":"2026-09-22","title":"ΟΗΕ – Μακρόν: «Ποια ειρήνη; Ούτε ένας ανθρωπιστικός διάδρομος δεν έχει ανοίξει στη Γάζα»","url":"https://www.tovima.gr/2026/09/23/world/oie-makron-poia-eirini-oute-enas-anthropistikos-diadromos-den-exei-anoiksei-sti-gaza","tone":"neutral"},{"outlet":"Newsbomb","date":"2026-09-22","title":"Μακρόν στον ΟΗΕ: «Ο νόμος της ζούγκλας επιστρέφει»– Σκληρό μήνυμα για Γάζα, Ουκρανία και διεθνή τάξη","url":"https://www.newsbomb.gr/kosmos/story/1765295/makron-ston-oie-o-nomos-tis-zoygklas-epistrefei---skliro-minyma-gia-gaza-oukrania-kai-diethni-taksi","tone":"neutral"}],"transcript":[{"t":0,"topic":"Imperialism","text":"of Luxembourg. The assembly will hear an address by His Excellency Emanuel Mron, president of the French Republic. I request protocol to escort his excellency and invite him to address the assembly. Madame President, &gt;&gt; Madame President, Deputy Secretary Majesties, Heads of State and distinguished delegates, dear friends, Since this morning, we've heard a number of speeches from this rostrm about the state of the world and I fear I will not be very original in my Every speaker has described the return of imperialism, of arrogance, the return of unrestrained force which knows no rules."},{"t":87,"topic":"International order","text":"A world in which we see power concentrated in the hands of the A world in which some believe that they can undermine the international order so as to push their borders outwards. those that believe that uh people's sovereignty can be toppled over that they could use that sovereignty. People who believe that they can decide the fate of the planet whether that be as regards the climate or AI. The question we must answer is very The question is, do we want to live under this state of affairs with a return to the law of the jungle or do we want to live in a civilized international society? Our duty today more than ever is to hold firm here at the United Nations in order to make decisions to further our common interests so that people can choose their fate freely, their development model, choose their future to refuse their sovereignty, being taken hostage by injust forces, unjust forces, by fear."},{"t":165,"topic":"UN reform","text":"Yeah. Therefore, the very razondetra of this organization is to bring together free people on an evil equin even footing, an equal footing. It is our charter that prevents the power wielded by some from making decisions for others. This is what compels us to work together to demonstrate our commitment and our to act and usefully so. You know just how committed France is to the United Nations and its ability to shoulder the responsibilities conferred upon it by the charter. I wish to reassert our commitment to take action hand in hand with each and every one of you so as to revive multilateralism and to demonstrate that we are stronger, more effective, more capable of tackling common challenges if we do this together. Today's challenges, future challenges, ones we do not know about yet, challenges we haven't yet tackled."},{"t":231,"topic":"Global conflicts","text":"I talked about the climate. It also applies to war and peace, new technologies and development. Across all of these areas, wherever might is right is being imposed, we must defend justice and our common interests. And it is in the interests of each and every one of us as well. Because our charter affords us the protection, the right to live together. Given the sorry state of the world, given what we're seeing today, and that is a growing number of wars we haven't solved, multiplying myriad crises and contemporary challenges which are weighing on new generations in new ways. I believe we are duty bound not to yield. And at the end of the day, the message I wish to convey to you today, as I've been doing over the last nine years, is a message of determination, optimism through action. What I'm trying to tell you is that we will not yield to fatalism, to defeatism, which I very much invogue."},{"t":302,"topic":"International law","text":"According to this rhetoric, there's not much point coming here to deliver They say might is right. We can impose a different kind of peace. That is what they say. But we will not give in to that kind of rhetoric. Even less so today. We will not yield across five areas. The first is fatalism in the face of war and suffering. We must recommmit to finding concrete solutions to building peace. International law never claimed to describe reality. It talked about the limits which sovereign nations themselves set. And in order to ensure when there's a disagreement, force is not the only recourse we have and as an option on the table, we must learn the lessons of the 20th century. Those who've forgotten those lessons are committing both a moral error and a political mistake. That is the reality of the situation in the Middle East, in Ukraine, in Africa."},{"t":368,"topic":"Israel-Gaza","text":"War crimes have been industrialized. We've seen the destruction of civilian infrastructure, human rights violations. It's a new era of barbaric acts. The Geneva Conventions offered a protective framework, but it is being Alfa, Bukavo, Gaza, the list goes on. Together with Jordan and the ICRC, France is going to continue undertaking efforts to ensure the international effort that aims to uphold international humanitarian law, which over 116 states have already rallied behind, will help us to keep our commitments. We must mobilize time and time again to defend international law and international humanitarian law at this time of war. As we've often said, there cannot be peace without justice. And that is why France continues to support politically and the international mechanism aimed at uh collecting evidence and ensuring justice in particular to factf finding missions."},{"t":434,"topic":"UN reform","text":"We will continue lending our support to the International Court of Justice and supporting the central role it plays. We cannot simply accept this new order of impunity which some are trying to erect. This is why that why at the security council France supports reforms aimed at bolstering its effectiveness. We must open up to new members, new regions, first and foremost Africa. But in terms of the substance, the security council must be able to take action in the face of mass violations of international law. Who can accept a procedural deadlock when we see barbaric acts being committed? The Franco Mexican initiative on regulating the veto in the case of m mass atrocities being committed is needed more than ever and I'm delighted that it now has the support of 128 member states. The campaign will and we are seeking to secure the commitment of each and every permanent member of the security council for this But it's not enough invoking the law, invoking our values in order to uphold the obligations we all signed up to when we joined the United Nations."},{"t":518,"topic":"Ukraine","text":"We're duty bound to act and France stands ready working in concert with all those who wish to act in defense of the principles enshrined in the charter. All those who do not wish to remain powerless. The coalition of the willing on Ukraine together with the UK and Germany. A coalition which brings together everyone who stands ready to guarantee peace and stability in the very heart of Europe. The very place where two world wars began. something no one can ignore. And many in the room today know better than anyone what a return of war to Europe could mean. We will not yield an inch. The coalition of the willing will continue fighting. We also have an independent multinational coalition aimed at restoring the freedom of navigation in the Homus strait. This should not be used for blackmail. It's a cardinal principle of international law and it is in the interest of all of us for vessels to be able to transit through the straight securely so and for the energy interest of all of our countries to be secured."},{"t":585,"topic":"Africa","text":"The reopening of the homos strait is a priority. Respect for international law is also a priority. It is in everyone's interests and France is committed to it. Moving on to Africa. We shoulder a collective responsibility for the crisis crises which are piling up without any answers without any responses. Peace operations must be more effective and to this end they must be endowed endowed with adequate funding and better coordinated with the United States as well as host nations. Back in 2018 2018, I already mentioned the role played by regional and better coordination between these regional bodies and the UN at the Africa meeting in Nairobi with over 30 African heads of state and in Adisba the headquarters of the African Union together with the UN. We stated clearly that the African Union and regional organizations should be fully equipped to play their role as regards peace and security on the African continent."},{"t":648,"topic":"Africa","text":"In Paris in November, we will hold a meeting aimed at replenishing the African Union Peace Fund. This will be on the sidelines of the Paris Peace Forum. I call on all potential funders to make robust and concrete pledges. We will not yield in the face of war. We must recommmit and seek solutions that are in keeping with the spirit of the charter. Second, we must not give in to the permanent temptation to espouse double standards. This is what's devising uh this is what is dividing our problem, our planet. It is uh undermining the credibility of our organization and the charter. How many times have we heard that uh people's has value in Europe but if we look at the Middle East at Africa it is less valuable. No, that is unacceptable. We must defend the same principles across the board in the spirit of the charter support the sovereignty of all peoples."},{"t":714,"topic":"Ukraine","text":"We cannot substitute for their And every time some states wish to run rough road over the will of certain peoples to change a system to topple a regime. Every time this resulted in ever greater chaos, no double standards. A life is a life. Peace and security are indivisible and everyone has a right to them. in Ukraine. For almost 5 years now, Russia has been waging a cruel war on civilians. It's been occupying the territory of a sovereign state. France will continue providing unstinting support for the legitimate aspirations of the Ukrainian people to peace, security, and to a future. At the same time, we will spend no effort to ensure that useful negotiations between Russia and Ukraine begin as swiftly as possible. We must defend Ukrainians more than ever as winter is coming."},{"t":776,"topic":"Ukraine","text":"We must defend them on the energy front. We must give them more interceptors. We must protect the civilian population. And this is why we'd like to express our support. A double moratorium, a moratorium on strikes on energy and civilian infrastructure. That's first. and a Black Sea moratorium which would allow us to release grain shipments. Addressing food security concerns, food security being so important for many emerging economies, for many developing nations. This double moratorium is a necessity. Let's put it on the table and uh let's confront Russia with this in the Middle East. We are also seeking peace and security for all. This is what we defend. Respect for sovereignty in Lebanon."},{"t":839,"topic":"Lebanon","text":"Displaced Lebanese people. Their villages are being u raised in the south. Only a fully sovereign Lebanon will be able to disarm Hezbollah and restore security for all Lebanese and their neighbors. Sovereignty for Lebanon and its people, sovereignty for Palestinians, their very basic, their most basic rights are once again being violated. One year ago, in this very chamber, several dozen states recognized Palestine. I understand that some are very cynical. You recognized it on paper. Look at the reality of the situation. But what is our credibility worth if we remain inactive on Gaza? Some claim that uh peace has been achieved but this has not opened up humanitarian deliveries. The spectacle the spectacle it is shameful."},{"t":902,"topic":"Israel-Gaza","text":"Shame on all of us. Look, just look at look at what's happening in the West Bank where day in day out we are seeing violations and in the name of what Hamas was never very active in the West What what we need is respect for the legitimate rights of the Palestinian people, their legitimate right to exist. This is a prerequisite for security today and tomorrow for the people of their security, their very existence to which we're very committed. But all those who claim that Israel's security requires a violation of the sovereignty of all of its neighboring states are making very fateful error. They are weakening Israel's security today and going forward. They are threatening Israel security. In fact, sovereignty for Syria as well."},{"t":966,"topic":"Syria","text":"The revolution should not turn into a disappointment. A few months ago in Damascus, I lent France's support to building a free Syria, and we must continue these efforts, allowing Syria to fully reassert its sovereignty and unity. France is committed across all of these fronts just like we're committed with Italy with the help of Jordan and other friends of Lebanon. We've been committed for 50 years to all Lebanese. So no double standards sovereignty for all peoples across the board. My third conviction is that we must not yield to a divided world. Many describe this rift. Many talk about this rift between the north and the south. We won't be able to tackle any of the challenges our planet faces if we give in to this rift."},{"t":1030,"topic":"Africa","text":"And it is fueled by double standards. This rift. However, we need the north and the south to reconcile so that they can tackle climate health development challenges. And that's why over the last few years, we've launched many more initiatives. For instance, the Kovac initiative in response to CO in partnership with the WHO and the African when it came to shoring up economies together with the International Monetary Fund to reform special drawing rights and uh make progress for African economies. And we held our word hundred billion dollars in special drawing allocated to helping African countries. We must stay the course ensuring that we remain united without pitting anyone against anyone else. That is why it's important that the global health infrastructure must remain intact. We will continue reforming that architecture, but we will never weaken the WH."},{"t":1094,"topic":"Africa","text":"We must put the finishing touches on the pandemic's and CDC Africa and the WH should be in a position to combat Ebola ever more effectively. We must be clearsighted as we reform our official development assistance, ODA. We must ensure that our investments exhibit greater solidarity that they're more effective. This is what we did with the Paris Pact for People and Planet in 2023. Also at the Africa Forward Summit in Nairobi, we also agreed to build a new consensus around investment that stands in solidarity with other states. Countries are allocating funds and yet the needs of the countries of the of the global south are growing as well. We need to go faster and go further to help the INF and the World Bank to be more effective. We must bolster the effectiveness of the instruments at their disposal so that we can mobilize the private sector better creating guarantee mechanisms to ensure that uh in emerging economies, middle- inome countries and developing countries, a more effective response can be mounted to the problems they face."},{"t":1165,"topic":"Cultural restitution","text":"This is the kind of new partnership we must forge in order to ensure that there is no gap, no division between the north and the south. In a similar vein, this north south partnership requires and will require us to wield our capacity to reopen a dialogue about our common history, our cultural relationships and remembrance. This is what France has tried to do over the last few years. Working on the basis of joint scientific works, we've instituted a number of you a number of bills to ensure that we restitute cultural artifacts in a way forging a partnership in the name of culture, history and remembrance and this with a number of uh countries of the south for instance with Ghana and together with all interested parties all interested partners we will work on restorative justice reparations ions. This is a matter of respect and it is on this uh respect that uh the partnership between the north north and the south will be built."},{"t":1238,"topic":"Global trade","text":"Moving on, global trade, it needs to be more effective and more equitable. This is what we sought to achieve at the G7 meeting France convened. Bringing together countries of the south, ensuring that there is common ground, a dialogue going beyond the G7 with China, India, Brazil, South Korea, the list goes on. so that we can improve our collective ensure that uh we work on rare earth rare earth metals, critical minerals as well as other areas. At the end of the day, we must shoulder this responsibility ensuring that there is no rift between these two blocks. And in a similar fashion, we must not yield on the climate and biodiversity. We've done a great deal over the last few years, ever since the Paris Agreement 11 years ago."},{"t":1304,"topic":"Ocean","text":"The principles are still valid today and must be defended. We must stay the course. But I understand the doubts some harbor on this front. Let us not seed. If we are to defend our planet, defend the climate, defend biodiversity. We need proactive multilateralism. And this is what we tried to achieve at the One Planet Summit. It's what we also tried to do acting together. And we we did it. Just look at the oceans. A few years ago, everybody said it was to craft agreements so as to protect uh marine areas, protect the oceans. Just look at what we've done over the last few years, protecting 20 years of uh our land mass and our seas. We've crafted this agreement and implementation is improving year in year out. Some also some also told us that we won't be able wouldn't be able to conserve twothirds of uh our oceans the high seas."},{"t":1378,"topic":"Ocean","text":"We undertook those negotiations working handinhand with the great powers. That's the BB&amp;J agreement. And in a matter of we achieved over 60 ratifications, which means that the treaty has now entered into force that agreement. The NICE the United Nations Ocean Conference, the third oceans conference last year helped us to accelerate that work and the first oceans COP will be held in a few months time in January. This is tremendous evidence of our ability to achieve concrete results when we mobilize, when we act in concert. So, let's not give in to fatalism. Let's defend what we've achieved, but also our principles. We must defend free and independent science. Let's protect the IPCC it best."},{"t":1439,"topic":"AI","text":"We need scientists who measure, who analyze, who assess. Let's uphold our commitment to the Paris Agreement, to our decarbonization pathways, to our 2050 carbon neutrality target. Let's shoulder our share of responsibility. We need to innovate, cooperate, restart work on biodiversity credits, and achieve our objectives on forests and oceans. We have many decisions to take. We cannot give in to fatalism. We are already the victims of climate change. We must do it for them and even more so for our children. Last but not least, we must hold fast and not yield on artificial intelligence. There are some who wish to make us believe that only two powers, the US and China will be taking the decisions. They want us to believe that just a few economic actors will make all the decisions. the kinds of economic innovations that will be implemented whether they want to take a break or not."},{"t":1503,"topic":"AI","text":"The kinds of innovations that uh happen. Some of these uh technological developments might attack the security of our states, our hospitals, of banks. They say that just a few will decide what kind of society we live in. No. No. Starting in 2008 at the G7 with our Canadian friends, we launched the global partnership for artificial intelligence under the opaces of the OECD to kickstart discussions on the need for at the AI summit in 2025. The AI governance summit the next edition will be held in in Switzerland next year. There was also the Indian edition. We advocated for two very simple things. For everyone in the world to have their own LLM model capabilities, calculation capabilities, AI capabilities so that we can craft a way of auditing these models instead of being reliant on just a few private actors."},{"t":1571,"topic":"AI","text":"And in fact, Europe was the first with the AI act to take forward these principles to take forward these models and we must continue down that path. Therefore, I wish to emphasize a particular point, our young people and our children. For far too long, we've protected we've spent far too long not protecting our young people and adolescence. And as a result, we're living with the consequence. their capacity to learn is in decline. We're seeing mental health The facts are stark and uh the correlation is clear-cut. That's why we've kickstarted a large scale initiative aimed at protecting our young people, our adolescents to stop them accessing social networks before the age of 15 underway in various countries. And I wish to commend our Australian colleagues, the first to take legislation on this front."},{"t":1634,"topic":"AI","text":"We must continue down this path and see it through. But let's not wait for the consequences to come raining down on AI. We must act now to protect our children and our young people. Look at the impact chatbots have on our children. This is why together with Kenya, Spain, we've built a coalition on children's in the era of AI. We are mobilizing already this afternoon and also at the Paris Peace Forum at the Paris Peace Forum at on the 10th and 11th of November of this year. governments, organizations, public and private actors, academics, private companies, everyone will be rallying behind this agenda. So, I hope to see you on the 10th and 11th of November in Paris. Going beyond that, we can clearly see the race that is underway in cutting edge models. We must all be investing and France is proud to have a competitive frontier model and We will continue supporting them so that we can have this kind of model but we we must also forge new kinds of cooperation and I very much hope and wish for all sovereign states committed to their independence Indian Brazilian African Gulf states Singapore the"},{"t":1724,"topic":"AI","text":"list goes on this independent coalition which I mentioned earlier I don't want anyone to become the vessel of one of the great powers. Rather, we must come together to build an open-source frontier model, a cutting edge model using all of the capabilities you have, pooling them. Our investment capabilities must be pulled to build a cutting edge opensource AI model which we will share. We should not depend on somebody else. This is the agenda we must take forward and this through cooperation. Furthermore, there are other areas where we must set new rules AI in out of spa out of space, AI and defense and cyber security. This has very serious consequences which uh affect the very heart of our national security. in Evion at the G7."},{"t":1789,"topic":"AI","text":"Many of us lent our support for the call launched by our Finnish and Norwegian friends and we want to continue within the framework of the G7 but also working closely with our UK colleagues who will hold the chair of the G20 next year. We want to set a cooperation agenda on AI so as to protect the most sensible the most sensitive components thereof which affect our national security. We are coming to an agreement to build a new international architecture. We did this on chemical weapons. We did this when it came to other risks and we must do the same when it comes to outer space, defense, cyber security issues on which we must take control and we need very specific kinds of cooperation, a specific framework for cooperation between member states in these areas so as to be able to take this cooperation forward within a specific framework. We must not yield on this either."},{"t":1853,"topic":"Multilateralism","text":"These are the five key areas. I could have been more exhaustive in my comments, but I'll leave it there. This is what France will be defending across these five areas. My message is to stand firm. Do not yield to the situation which is developing. The world is slowly becoming more The rhetoric of defeat that is giving way to empires abusing their powers, threatening the sovereignty of some nations, abuse of power by some who are monopolizing productive capacity, those who are monopolizing the ability to make calculations, abuses of power by those who wish to concentrate wealth in their own hands. In the face of such abuses of power, we must go back to the very spirit of this organization, which is multilateralism."},{"t":1919,"topic":"UN reform","text":"The defense of common interests of justice for all. Something that through unity, justice, and cooperation is the way to take effective action. the way to restore just and lasting peace in all of our nations. A way to once again achieve unity between the North and the South. A way of crafting an agenda for taking proactive measures on technology, on the climate. We will not yield today more than ever. We need the United Nations as we elect a new Secretary General. And I'd like to pay tribute to the efforts of Antonio Gutish over all these years under such testing conditions. He never gave in. We must address old crises, tackle new challenges. Against this backdrop, we must continue taking action today more than ever."},{"t":1983,"topic":"Ceremony","text":"We must be courageous in our optimism. We must mobilize to take useful steps not to yield for the benefit of each and every one of us. Long live the United Nations. I thank you. On behalf of the assembly, I wish to thank the president of the French The assembly will"}],"compare":[{"topic":"Artificial Intelligence","share":0.21,"mean":0.0496,"rank":8,"others":83},{"topic":"International Law & Order","share":0.1851,"mean":0.0597,"rank":20,"others":102},{"topic":"Africa","share":0.1341,"mean":0.0229,"rank":12,"others":36},{"topic":"UN & its reform","share":0.1084,"mean":0.2053,"rank":139,"others":170},{"topic":"Russia-Ukraine War","share":0.0972,"mean":0.035,"rank":23,"others":44},{"topic":"Ocean Governance","share":0.0681,"mean":0.0064,"rank":8,"others":16},{"topic":"Israel–Palestine","share":0.0652,"mean":0.0523,"rank":59,"others":76},{"topic":"Cultural Restitution","share":0.035,"mean":0.0005,"rank":2,"others":1}]};
